import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:hr_oto_design_system/hr_oto_design_system.dart';
import 'package:http/http.dart' as http;

const apiUrl = String.fromEnvironment('HR_OTO_API_URL', defaultValue: 'http://localhost:8000/api/v1');
final adminApiProvider = Provider((_) => AdminApi(apiUrl));

class AdminApi {
  AdminApi(this.base); final String base; final storage = const FlutterSecureStorage(); String? token;
  Map<String,String> get headers => {'Content-Type':'application/json', if (token != null) 'Authorization':'Bearer $token'};
  dynamic decode(http.Response r) { final x = r.body.isEmpty ? {} : jsonDecode(r.body); if (r.statusCode < 200 || r.statusCode >= 300) throw Exception(x is Map && x['detail'] != null ? x['detail'] : 'API შეცდომა'); return x; }
  Future<void> login(String email, String password, String? mfa) async { final r = await http.post(Uri.parse('$base/auth/login'), headers: headers, body: jsonEncode({'email':email,'password':password,if (mfa != null && mfa.isNotEmpty) 'mfa_code':mfa})); token = decode(r)['access_token']; await storage.write(key:'admin_token', value:token); }
  Future<Map<String,dynamic>> dashboard(String code) async => Map<String,dynamic>.from(decode(await http.get(Uri.parse('$base/admin/$code/dashboard'),headers:headers)));
  Future<List<Map<String,dynamic>>> employees(String code, {String search='', String status='active'}) async { final uri=Uri.parse('$base/admin/$code/employees').replace(queryParameters:{'search':search,'status':status}); return (decode(await http.get(uri,headers:headers)) as List).cast<Map<String,dynamic>>(); }
  Future<void> createEmployee(String code, Map<String,dynamic> data) async { decode(await http.post(Uri.parse('$base/admin/$code/employees'),headers:headers,body:jsonEncode(data))); }
  Future<Map<String,dynamic>> entitlements(String code) async => Map<String,dynamic>.from(decode(await http.get(Uri.parse('$base/admin/$code/entitlements'),headers:headers)));
  Future<List<dynamic>> leaveRequests(String code) async => decode(await http.get(Uri.parse('$base/admin/$code/leave/requests'),headers:headers)) as List<dynamic>;
}

void main() => runApp(const ProviderScope(child: AdminApp()));
class AdminApp extends StatefulWidget { const AdminApp({super.key}); @override State<AdminApp> createState()=>_AdminAppState(); }
class _AdminAppState extends State<AdminApp> { ThemeMode mode=ThemeMode.system; bool logged=false; String code=''; @override Widget build(BuildContext c)=>MaterialApp(title:'HR-OTO Admin',debugShowCheckedModeBanner:false,theme:HrOtoTheme.light(),darkTheme:HrOtoTheme.dark(),themeMode:mode,home:logged?AdminWorkspace(code:code,onTheme:()=>setState(()=>mode=mode==ThemeMode.dark?ThemeMode.light:ThemeMode.dark)):AdminLogin(onLogged:(v)=>setState((){code=v;logged=true;}))); }

class AdminLogin extends ConsumerStatefulWidget { const AdminLogin({super.key,required this.onLogged}); final ValueChanged<String> onLogged; @override ConsumerState<AdminLogin> createState()=>_AdminLoginState(); }
class _AdminLoginState extends ConsumerState<AdminLogin> { final email=TextEditingController(),password=TextEditingController(),mfa=TextEditingController(),code=TextEditingController(); bool busy=false; String? error; @override Widget build(BuildContext c)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:460),child:Card(child:Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[const HrOtoLogo(size:92),Text('HR-OTO Admin',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)),const SizedBox(height:20),TextField(controller:code,decoration:const InputDecoration(labelText:'Company Code')),TextField(controller:email,decoration:const InputDecoration(labelText:'ელფოსტა')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'პაროლი')),TextField(controller:mfa,decoration:const InputDecoration(labelText:'MFA კოდი')),if(error!=null)Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error)),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:_login,child:Text(busy?'...':'შესვლა')))])))))); Future<void> _login() async { setState(()=>busy=true); try { await ref.read(adminApiProvider).login(email.text,password.text,mfa.text); widget.onLogged(code.text.trim().toUpperCase()); } catch(e) { setState(()=>error=e.toString()); } finally { if(mounted)setState(()=>busy=false); } } }

class AdminWorkspace extends StatefulWidget { const AdminWorkspace({super.key,required this.code,required this.onTheme}); final String code; final VoidCallback onTheme; @override State<AdminWorkspace> createState()=>_AdminWorkspaceState(); }
class _AdminWorkspaceState extends State<AdminWorkspace> { int index=0; final labels=['Dashboard','თანამშრომლები','ორგანიზაცია','პაკეტი / პარამეტრები']; final icons=[Icons.dashboard_outlined,Icons.people_outline,Icons.account_tree_outlined,Icons.settings_outlined]; @override Widget build(BuildContext c){ final wide=MediaQuery.sizeOf(c).width>=760; final pages=[AdminDashboard(code:widget.code),EmployeesPage(code:widget.code),OrganizationPage(code:widget.code),CompanySettingsPage(code:widget.code)]; return Scaffold(appBar:AppBar(title:Text('HR-OTO Admin • ${labels[index]}'),actions:[IconButton(onPressed:widget.onTheme,icon:const Icon(Icons.brightness_6_outlined))]),body:Row(children:[if(wide)NavigationRail(selectedIndex:index,labelType:NavigationRailLabelType.all,onDestinationSelected:(x)=>setState(()=>index=x),destinations:[for(var i=0;i<labels.length;i++)NavigationRailDestination(icon:Icon(icons[i]),label:Text(labels[i]))]),if(wide)const VerticalDivider(width:1),Expanded(child:pages[index])]),bottomNavigationBar:wide?null:NavigationBar(selectedIndex:index,onDestinationSelected:(x)=>setState(()=>index=x),destinations:[for(var i=0;i<labels.length;i++)NavigationDestination(icon:Icon(icons[i]),label:labels[i])])); } }

class AdminDashboard extends ConsumerStatefulWidget { const AdminDashboard({super.key,required this.code}); final String code; @override ConsumerState<AdminDashboard> createState()=>_AdminDashboardState(); }
class _AdminDashboardState extends ConsumerState<AdminDashboard>{ late Future<Map<String,dynamic>> future; @override void initState(){super.initState();future=ref.read(adminApiProvider).dashboard(widget.code);} @override Widget build(BuildContext c)=>FutureBuilder(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text(s.error.toString()));final d=s.data!;return ListView(padding:const EdgeInsets.all(24),children:[Text('მთავარი Dashboard',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:20),Wrap(spacing:16,runSpacing:16,children:[_Metric('თანამშრომლები',d['employees']),_Metric('არქივირებული',d['archived_employees']),_Metric('ფილიალები',d['branches']),_Metric('განყოფილებები',d['departments'])])]);});}
class _Metric extends StatelessWidget{const _Metric(this.name,this.value);final String name;final dynamic value;@override Widget build(BuildContext c)=>SizedBox(width:210,child:Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('$value',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),Text(name)]))));}

class EmployeesPage extends ConsumerStatefulWidget { const EmployeesPage({super.key,required this.code}); final String code; @override ConsumerState<EmployeesPage> createState()=>_EmployeesPageState(); }
class _EmployeesPageState extends ConsumerState<EmployeesPage>{ final search=TextEditingController(); String status='active'; late Future<List<Map<String,dynamic>>> future; @override void initState(){super.initState();future=_load();} Future<List<Map<String,dynamic>>> _load()=>ref.read(adminApiProvider).employees(widget.code,search:search.text,status:status); void reload()=>setState(()=>future=_load()); @override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(24),child:Row(children:[Expanded(child:TextField(controller:search,onSubmitted:(_)=>reload(),decoration:const InputDecoration(labelText:'ძებნა Employee ID / სახელი / ელფოსტა',prefixIcon:Icon(Icons.search)))),const SizedBox(width:12),DropdownButton(value:status,items:const[DropdownMenuItem(value:'active',child:Text('აქტიური')),DropdownMenuItem(value:'archived',child:Text('არქივი'))],onChanged:(x){if(x!=null){status=x;reload();}}),const SizedBox(width:12),FilledButton.icon(onPressed:()=>_create(),icon:const Icon(Icons.add),label:const Text('დამატება'))])),Expanded(child:FutureBuilder(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text(s.error.toString()));final rows=s.data!;return ListView.separated(padding:const EdgeInsets.symmetric(horizontal:24),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,i){final e=rows[i];return Card(child:ListTile(leading:CircleAvatar(child:Text(e['first_name'].toString().substring(0,1))),title:Text('${e['first_name']} ${e['last_name']}'),subtitle:Text('${e['employee_id']} • ${e['email']}'),trailing:const Icon(Icons.chevron_right)));});}))]); Future<void> _create()async{final id=TextEditingController(),first=TextEditingController(),last=TextEditingController(),email=TextEditingController();await showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('თანამშრომლის დამატება'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:id,decoration:const InputDecoration(labelText:'Employee ID')),TextField(controller:first,decoration:const InputDecoration(labelText:'სახელი')),TextField(controller:last,decoration:const InputDecoration(labelText:'გვარი')),TextField(controller:email,decoration:const InputDecoration(labelText:'ელფოსტა'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('გაუქმება')),FilledButton(onPressed:()async{try{await ref.read(adminApiProvider).createEmployee(widget.code,{'employee_id':id.text,'first_name':first.text,'last_name':last.text,'email':email.text});if(d.mounted)Navigator.pop(d);reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}},child:const Text('შენახვა'))]));}}

class OrganizationPage extends StatelessWidget { const OrganizationPage({super.key,required this.code}); final String code; @override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(24),children:const[Text('ორგანიზაცია',style:TextStyle(fontSize:24,fontWeight:FontWeight.w700)),SizedBox(height:12),ListTile(leading:Icon(Icons.account_tree),title:Text('განყოფილებები / პოზიციები / ფილიალები'),subtitle:Text('მართვა API-ით მზადაა; ჩანაწერები Tenant Database-ში ინახება.')),ListTile(leading:Icon(Icons.manage_accounts),title:Text('მომხმარებლები და უფლებები'),subtitle:Text('Company Owner / HR Admin / Manager უფლებები server-side კონტროლდება.'))]);}
class CompanySettingsPage extends ConsumerWidget { const CompanySettingsPage({super.key,required this.code}); final String code; @override Widget build(BuildContext c,WidgetRef ref)=>FutureBuilder(future:ref.read(adminApiProvider).entitlements(code),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text(s.error.toString()));final d=s.data!;return ListView(padding:const EdgeInsets.all(24),children:[const Text('პაკეტი, ფუნქციები და ლიმიტები',style:TextStyle(fontSize:24,fontWeight:FontWeight.w700)),const SizedBox(height:12),Text('Features: ${d['features']}'),const SizedBox(height:8),Text('Limits: ${d['limits']}'),const SizedBox(height:24),const Text('შეტყობინებების არხები იმართება Owner-ის provider policy-ის ფარგლებში.')]);});}
